mapper.select:
SELECT r.id AS id, m.id AS memberId, m.name, m.unique_id, m.profile_image, r.content, r.like_count, FALSE AS liked_by_me, r.created_at, r.updated_at FROM reply r JOIN post p ON r.post_id = p.id JOIN member m ON r.member_id = m.id
AND r.post_id = #{postId}
AND NOT EXISTS ( SELECT 1 FROM block b WHERE b.member_id = #{memberId} AND b.blocked_id = r.member_id )
AND r.id > #{cursor}
ORDER BY r.id ASC LIMIT #{limit}

mapper.update:
UPDATE reply
SET content = #{content}
WHERE id = #{id}

UPDATE reply
SET like_count = like_count + 1
WHERE id = #{replyId}

UPDATE reply
SET like_count = GREATEST(like_count - 1, 0)
WHERE id = #{replyId}
